import LottieView from 'lottie-react-native';
import { StyleSheet, useWindowDimensions } from 'react-native';
import type { Verdict } from '../types';

// Generated by scripts/make-lottie.mjs
const animations = {
  idle: require('../../assets/lottie/idle.json'),
  scanning: require('../../assets/lottie/scanning.json'),
  happy: require('../../assets/lottie/happy.json'),
  okay: require('../../assets/lottie/okay.json'),
  sad: require('../../assets/lottie/sad.json'),
};

export type Mood = keyof typeof animations;

export const moodForVerdict: Record<Verdict, Mood> = { CLEAN: 'happy', OKAY: 'okay', BAD: 'sad' };

/** The sugar-cube character, standing in the bottom-left corner above `bottom`. */
export function Character({ mood, bottom }: { mood: Mood; bottom: number }) {
  const { width } = useWindowDimensions();
  const size = Math.min(width * 0.5, 230);
  return (
    <LottieView
      key={mood}
      source={animations[mood]}
      autoPlay
      loop
      style={[styles.character, { width: size, height: size, bottom }]}
    />
  );
}

const styles = StyleSheet.create({
  character: { position: 'absolute', left: 4 },
});
